                        + " WHERE table_schema = 'PUBLIC' AND table_name = ? AND is_generated = 'NEVER'"
                        + " ORDER BY ordinal_position",
                (rs, n) -> new Column(rs.getString(1), "YES".equals(rs.getString(2)), rs.getString(3) != null), t));
    }
